import{_ as e,o as s,c as i,a2 as t}from"./chunks/framework.BvlN9b-o.js";const b=JSON.parse('{"title":"当前成员锁与角色生命周期","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/members","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/members.md","filePath":"tutorials/members.md"}'),r={name:"tutorials/members.md"};function n(o,a,p,l,h,c){return s(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="当前成员锁与角色生命周期" tabindex="-1">当前成员锁与角色生命周期 <a class="header-anchor" href="#当前成员锁与角色生命周期" aria-label="Permalink to &quot;当前成员锁与角色生命周期&quot;">​</a></h1><p>目标：让自己的业务写入与成员降级、停用有明确提交顺序，并复用现有成员管理。前提是已有 <a href="./sessions">Session</a>，理解资源授权；一次部署对应一个 Organization。</p><p>完整参考：<a href="./library-grants">资源授权</a>。</p><h2 id="公共接口与用法" tabindex="-1">公共接口与用法 <a class="header-anchor" href="#公共接口与用法" aria-label="Permalink to &quot;公共接口与用法&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/organization/mod.rs" target="_blank" rel="noreferrer">Organization</a>提供 <code>MemberRole::{Owner, Admin, Member}</code>、<code>active_role_in</code> 和 <code>lock_memberships</code>。在业务事务中调用，锁持续到自己 commit/rollback；SQL 摘录：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> saas_core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">memberships</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> active</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FOR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SHARE</span></span></code></pre></div><p><code>None</code> 表示没有有效成员身份。多个受影响成员通过 <code>lock_memberships(&amp;mut tx, &amp;ids)</code> 按 ID 顺序取共享锁，再锁资源；不在已锁资源后补取无序成员锁。详细签名见授权指南。</p><p>完整参考：<a href="./library-grants">授权指南</a>。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/identity/mod.rs" target="_blank" rel="noreferrer">Identity</a>公开 <code>profiles(connection, ids)</code> 批量读成员资料，以及 <code>revoke_user_sessions(connection, user_id)</code> 同事务撤销会话。自己的模块通过这些能力协作，不跨模块 JOIN 私有凭据表，也不每人一次查资料。</p><h2 id="使用已有管理-api" tabindex="-1">使用已有管理 API <a class="header-anchor" href="#使用已有管理-api" aria-label="Permalink to &quot;使用已有管理 API&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/organization/management.rs" target="_blank" rel="noreferrer">管理 Handler/用例</a>提供分页成员列表和 <code>PUT /api/v1/organization/members/{user_id}</code>，输入 <code>role / active / version</code>。列表默认 50、最多 100，游标绑定管理员；旧 version 返回 409。Owner 可管理 Owner，Admin 只管理非 Owner，Member 拒绝。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/src/modules/organization/domain.rs" target="_blank" rel="noreferrer">纯规则</a>与事务共同保护最后 Owner：先锁 Organization 唯一行，再按 ID 顺序锁操作者/目标，在事务内检查有效 Owner 集合、角色、版本，更新成员、撤销必要 Session、写 Audit 并提交。不能在事务外 count 后独立 update。</p><p>降级或停用最后有效 Owner 返回 <code>422 organization.last_owner</code>。两个 Owner 同时退出只能一个成功；首次注册也使用同一协调行。</p><h2 id="停用不能被重新启用复活" tabindex="-1">停用不能被重新启用复活 <a class="header-anchor" href="#停用不能被重新启用复活" aria-label="Permalink to &quot;停用不能被重新启用复活&quot;">​</a></h2><p>停用成员与撤销全部旧 Session、密码重置材料、Audit 同事务提交；重新启用后旧 Cookie 仍无效，用户需重新登录。Session 签发也持有成员锁，因此与停用形成一致提交顺序。Audit 失败全部回滚。</p><p>业务写入持有 Membership 共享锁，管理变更取排他锁。鉴权时返回的角色、客户端下拉框或之前缓存的资格不能替代当前事务检查。已有独立 API Keys 由每次认证的 active 检查约束，密码重置不自动撤销它们。</p><h2 id="验证自己的接入" tabindex="-1">验证自己的接入 <a class="header-anchor" href="#验证自己的接入" aria-label="Permalink to &quot;验证自己的接入&quot;">​</a></h2><p>在仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> members</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> membership_policy</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/api/tests/members.rs" target="_blank" rel="noreferrer">真实 HTTP 检查</a>覆盖角色矩阵、版本冲突、最后 Owner 并发、Audit 回滚、停用/重启用和登录竞态；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/crates/app/tests/membership_policy.rs" target="_blank" rel="noreferrer">纯规则检查</a>覆盖规则集合。自己的业务增加停用与写入受控竞态，证明写入只有合法的提交顺序。之后将锁纪律用于<a href="./attachments">文件完成</a>和<a href="./document-exports">后台发布</a>。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/08-members.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,22)])])}const k=e(r,[["render",n]]);export{b as __pageData,k as default};
